import * as fs from "node:fs";
import * as vscode from "vscode";
import { getDaemonLaunchSetting, getDaemonUrl, openLaunchSetting } from "./config";
import {
  DEFAULT_PROBE_INTERVAL_MS,
  DEFAULT_STARTUP_TIMEOUT_MS,
  probeDaemonHealth,
  waitForDaemon,
} from "./daemonHealth";
import {
  formatLaunchCommand,
  isSpeculative,
  resolveLaunchSpec,
  type DaemonLaunchSpec,
} from "./daemonLaunch";
import type { Store } from "./store";

const TERMINAL_NAME = "Jarvis Daemon";

/**
 * Starts jarvisd in a visible integrated terminal on explicit user action and
 * waits for it to answer the health probe.
 *
 * The daemon's Sentinel gates *agent-issued* execution; this is a user-issued
 * IDE launch, so it does not go through Sentinel — but nothing model-supplied
 * reaches it either: the spec is validated in `daemonLaunch.ts` and spawned as
 * an argv vector via `createTerminal({ shellPath, shellArgs })`, never as a
 * shell string.
 */
export class DaemonLauncher implements vscode.Disposable {
  private terminal: vscode.Terminal | undefined;
  private readonly closeListener: vscode.Disposable;
  private starting = false;
  private offlineNoticeShown = false;

  constructor(
    private readonly store: Store,
    private readonly log: (line: string) => void,
  ) {
    this.closeListener = vscode.window.onDidCloseTerminal((closed) => {
      if (closed === this.terminal) this.terminal = undefined;
    });
  }

  /** Implementation of `jarvis.startDaemon`. */
  async start(): Promise<void> {
    if (this.starting) {
      this.terminal?.show(true);
      return;
    }

    const url = getDaemonUrl();
    const existing = await probeDaemonHealth(url);
    if (existing.online) {
      void vscode.window.showInformationMessage(`Jarvis daemon is already running at ${url}.`);
      await this.store.refresh();
      return;
    }

    const resolution = resolveLaunchSpec({
      configured: getDaemonLaunchSetting(),
      workspaceFolders: (vscode.workspace.workspaceFolders ?? []).map((f) => f.uri.fsPath),
      exists: fileExists,
    });

    if (resolution.kind === "invalid") {
      this.log(`daemon launch spec rejected: ${resolution.reason}`);
      const choice = await vscode.window.showErrorMessage(
        `Jarvis: ${resolution.reason}`,
        "Configure",
      );
      if (choice === "Configure") await openLaunchSetting();
      return;
    }

    const spec = resolution.spec;
    this.log(`starting daemon (${resolution.kind}): ${formatLaunchCommand(spec)}`);
    this.launchTerminal(spec);

    this.starting = true;
    this.store.setConnecting(true);
    try {
      const result = await vscode.window.withProgress(
        {
          location: vscode.ProgressLocation.Notification,
          title: "Jarvis: starting the daemon…",
          cancellable: true,
        },
        (progress, token) =>
          waitForDaemon({
            probe: () => probeDaemonHealth(url),
            intervalMs: DEFAULT_PROBE_INTERVAL_MS,
            timeoutMs: DEFAULT_STARTUP_TIMEOUT_MS,
            isCancelled: () => token.isCancellationRequested,
            onAttempt: (attempt) => progress.report({ message: `probe ${attempt} · ${url}` }),
          }),
      );

      if (result.online) {
        this.log(`daemon online at ${url}${result.version ? ` · v${result.version}` : ""}`);
        void vscode.window.showInformationMessage(
          `Jarvis daemon is online${result.version ? ` (v${result.version})` : ""}.`,
        );
        return;
      }

      if (result.cancelled) {
        this.log("daemon startup wait cancelled by the user");
        return;
      }

      this.log(`daemon did not answer at ${url} after ${result.attempts} probes`);
      const hint = isSpeculative(resolution)
        ? " `jarvisd` may not be on PATH — set `jarvis.daemonLaunch` to how you run it."
        : " Check the Jarvis Daemon terminal for the failure.";
      const choice = await vscode.window.showErrorMessage(
        `Jarvis daemon did not come online within ${Math.round(DEFAULT_STARTUP_TIMEOUT_MS / 1000)}s at ${url}.${hint}`,
        "Show Terminal",
        "Configure",
      );
      if (choice === "Show Terminal") this.terminal?.show(true);
      else if (choice === "Configure") await openLaunchSetting();
    } finally {
      this.starting = false;
      this.store.setConnecting(false);
      await this.store.refresh();
    }
  }

  /**
   * Activation probe. When the daemon is not running, offers to start it once
   * per session — Forge is inert without it.
   */
  async offerStartIfOffline(): Promise<void> {
    const url = getDaemonUrl();
    const health = await probeDaemonHealth(url);
    if (health.online) {
      this.log(`daemon online at ${url}${health.version ? ` · v${health.version}` : ""}`);
      return;
    }
    this.log(`daemon offline at ${url}${health.detail ? ` (${health.detail})` : ""}`);
    if (this.offlineNoticeShown) return;
    this.offlineNoticeShown = true;

    const choice = await vscode.window.showInformationMessage(
      `Jarvis daemon (jarvisd) is not running at ${url}. Forge needs it for projects, workflows and approvals.`,
      "Start daemon",
      "Configure",
    );
    if (choice === "Start daemon") await this.start();
    else if (choice === "Configure") await openLaunchSetting();
  }

  private launchTerminal(spec: DaemonLaunchSpec): void {
    // A terminal from an earlier failed attempt is dead weight; replace it.
    this.terminal?.dispose();
    this.terminal = vscode.window.createTerminal({
      name: TERMINAL_NAME,
      shellPath: spec.command,
      shellArgs: [...spec.args],
      cwd: spec.cwd,
    });
    this.terminal.show(true);
  }

  /** Disposes the close listener only — the daemon terminal outlives the launcher. */
  dispose(): void {
    this.closeListener.dispose();
  }
}

function fileExists(path: string): boolean {
  try {
    return fs.existsSync(path);
  } catch {
    return false;
  }
}
