// Per-workflow facts distilled from the daemon's event feed.
//
// The router's choice, the reviewer's identity and the repair rounds are not on
// the workflow summary — they only exist as events. The Lens needs them for the
// agent orbs and the independence badge, so the event pump folds them into this
// map as it drains the feed. Pure and unit-tested.

import type { EventEnvelope } from "../model";
import { EMPTY_FACTS, type WorkflowFacts } from "./capsule";

export type FactsMap = Record<string, WorkflowFacts>;

function ensure(map: FactsMap, workflowId: string): WorkflowFacts {
  const existing = map[workflowId];
  if (existing) return existing;
  const created: WorkflowFacts = { ...EMPTY_FACTS, agents: [] };
  map[workflowId] = created;
  return created;
}

function stringField(event: EventEnvelope, key: string): string | undefined {
  const value = (event.data ?? {})[key];
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

/**
 * Folds one event into the map, in place. Returns true when something the UI
 * renders actually changed, so the caller can skip a redraw for the 122
 * `AgentSessionEvent.v1` lines a single run produces.
 */
export function applyEvent(map: FactsMap, event: EventEnvelope): boolean {
  const workflowId = stringField(event, "workflowId") ?? event.correlationId;
  if (!workflowId || !workflowId.startsWith("wf_")) return false;

  const facts = ensure(map, workflowId);
  facts.lastEventAt = event.occurredAt;

  switch (event.eventType) {
    case "AgentSelected.v1": {
      const agentId = stringField(event, "agentId");
      const role = (stringField(event, "role") ?? "").toLowerCase();
      if (!agentId) return false;
      if (!facts.agents.includes(agentId)) facts.agents.push(agentId);
      if (role === "reviewer") facts.reviewer = agentId;
      else if (role === "implementer") facts.implementer = agentId;
      facts.lastEventLabel = `router → ${agentId}`;
      return true;
    }
    case "PlanCreated.v1":
      facts.planned = true;
      facts.lastEventLabel = "plan sealed";
      return true;
    case "ReviewRepairRequested.v1":
      facts.repairRounds += 1;
      facts.lastEventLabel = `repair round ${facts.repairRounds}`;
      return true;
    case "WorkspaceIsolated.v1":
      facts.lastEventLabel = "worktree isolated";
      return true;
    case "VerificationCompleted.v1":
      facts.lastEventLabel = "verification green";
      return true;
    case "ReviewCompleted.v1":
      facts.lastEventLabel = "review complete";
      return true;
    case "EvidencePublished.v1":
      facts.lastEventLabel = "evidence sealed";
      return true;
    default:
      return false;
  }
}

/** Folds a batch, returning true when any of them mattered. */
export function applyEvents(map: FactsMap, events: readonly EventEnvelope[]): boolean {
  let changed = false;
  for (const event of events) {
    if (applyEvent(map, event)) changed = true;
  }
  return changed;
}

export function factsFor(map: FactsMap, workflowId: string): WorkflowFacts {
  return map[workflowId] ?? EMPTY_FACTS;
}
