import * as vscode from "vscode";
import { isActiveWorkflow } from "./model";
import { pipelineProgress, workflowStateLabel } from "./presentation";
import type { Snapshot, Store } from "./store";

/** Status-bar summary of the daemon: offline / idle / active workflow / approvals. */
export class StatusBar implements vscode.Disposable {
  private readonly item: vscode.StatusBarItem;

  constructor(store: Store) {
    this.item = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 100);
    this.item.command = "jarvis.workflows.focus";
    this.render(store.snapshot);
    this.item.show();
    store.onDidChange((snap) => this.render(snap));
  }

  private render(snap: Snapshot): void {
    if (!snap.online && snap.connecting) {
      this.item.text = "$(sync~spin) Jarvis: starting daemon…";
      this.item.tooltip = "Waiting for jarvisd to answer the health probe.";
      this.item.backgroundColor = new vscode.ThemeColor("statusBarItem.warningBackground");
      this.item.command = "jarvis.startDaemon";
      return;
    }

    if (!snap.online) {
      this.item.text = "$(debug-disconnect) Jarvis: daemon offline";
      this.item.tooltip = "jarvisd is not reachable. Click to start it (Jarvis: Start Daemon).";
      this.item.backgroundColor = new vscode.ThemeColor("statusBarItem.warningBackground");
      this.item.command = "jarvis.startDaemon";
      return;
    }

    this.item.backgroundColor = undefined;
    this.item.command = "jarvis.workflows.focus";
    const active = snap.workflows.find(isActiveWorkflow);
    const pending = snap.approvals.length;

    if (active) {
      this.item.text = `$(sync~spin) Jarvis · ${workflowStateLabel(active.state)} ${pipelineProgress(active.state)}%`;
      this.item.tooltip = `Workflow ${active.id} · ${active.state}`;
    } else if (pending > 0) {
      this.item.text = `$(clock) Jarvis · ${pending} approval${pending > 1 ? "s" : ""}`;
      this.item.tooltip = "Approvals waiting — open the Jarvis Forge view";
    } else {
      this.item.text = "$(rocket) Jarvis ready";
      this.item.tooltip = `${snap.status?.projectCount ?? 0} projects · ${snap.agents.filter((a) => a.available).length} agents online`;
    }
  }

  dispose(): void {
    this.item.dispose();
  }
}
