import * as vscode from "vscode";
import type { DaemonClient } from "./daemonClient";
import {
  addedRuns,
  findDiffFile,
  hunkRange,
  type DiffFile,
  type DiffHunk,
  type DiffSummary,
} from "./lens/diffHunks";
import type { Store } from "./store";

/**
 * Inline ghost diffs.
 *
 * An agent works in an isolated worktree, so the file you have open is NOT the
 * file it changed. These decorations project the agent's proposed hunks onto
 * your open buffer as glass-tinted ghost blocks, with an Accept / Reject / Why
 * lens above each one. Extension API only — decorations plus a CodeLens
 * provider, no core patch.
 *
 * Accept applies the hunk to the open document through a WorkspaceEdit, so the
 * change is a normal, undoable edit you can review before saving.
 */

interface GhostState {
  workflowId: string;
  summary: DiffSummary;
  /** `${fsPath}:${hunkIndex}` of hunks the user dismissed this session. */
  dismissed: Set<string>;
}

function hunkKey(uri: vscode.Uri, index: number): string {
  return `${uri.fsPath}:${index}`;
}

function clampRange(
  document: vscode.TextDocument,
  startLine: number,
  endLine: number,
): vscode.Range {
  const first = Math.min(Math.max(startLine - 1, 0), Math.max(document.lineCount - 1, 0));
  const last = Math.min(Math.max(endLine - 1, 0), Math.max(document.lineCount - 1, 0));
  return new vscode.Range(first, 0, last, document.lineAt(last).text.length);
}

/**
 * The ranges a hunk should paint in the open document.
 *
 * Only the lines the agent actually wrote: a hunk carries three lines of
 * unchanged context on each side, and tinting those claims the agent touched
 * code it never saw. A pure deletion has no added lines, so it falls back to
 * the single line the removal sat above.
 */
function ghostRanges(document: vscode.TextDocument, hunk: DiffHunk): vscode.Range[] {
  const runs = addedRuns(hunk);
  if (runs.length === 0) {
    const { startLine, endLine } = hunkRange(hunk);
    return [clampRange(document, startLine, endLine)];
  }
  return runs.map((run) => clampRange(document, run.startLine, run.endLine));
}

export class GhostDiffController implements vscode.Disposable {
  private state: GhostState | undefined;
  private readonly disposables: vscode.Disposable[] = [];
  private readonly onDidChangeLensesEmitter = new vscode.EventEmitter<void>();

  private readonly addedDecoration = vscode.window.createTextEditorDecorationType({
    isWholeLine: true,
    // A tint, not a fill: the ghost has to read as *proposed*, not as a marker.
    backgroundColor: new vscode.ThemeColor("jarvis.ghostAddedBackground"),
    borderColor: new vscode.ThemeColor("jarvis.ghostAddedBorder"),
    borderWidth: "0 0 0 2px",
    borderStyle: "solid",
    overviewRulerColor: new vscode.ThemeColor("jarvis.ghostAddedBorder"),
    overviewRulerLane: vscode.OverviewRulerLane.Right,
    rangeBehavior: vscode.DecorationRangeBehavior.ClosedClosed,
  });

  private readonly removedDecoration = vscode.window.createTextEditorDecorationType({
    isWholeLine: true,
    backgroundColor: new vscode.ThemeColor("jarvis.ghostRemovedBackground"),
    borderColor: new vscode.ThemeColor("jarvis.ghostRemovedBorder"),
    borderWidth: "0 0 0 2px",
    borderStyle: "solid",
    rangeBehavior: vscode.DecorationRangeBehavior.ClosedClosed,
  });

  constructor(
    private readonly client: DaemonClient,
    private readonly store: Store,
    private readonly seedIntent: (directive: string) => Promise<void>,
  ) {
    this.disposables.push(
      this.onDidChangeLensesEmitter,
      vscode.window.onDidChangeVisibleTextEditors(() => this.render()),
      vscode.workspace.onDidChangeTextDocument((e) => {
        // Editing invalidates the projected line numbers; drop the ghosts for
        // that file rather than decorating the wrong lines.
        if (this.state && this.fileFor(e.document)) this.render();
      }),
      vscode.languages.registerCodeLensProvider({ scheme: "file" }, {
        onDidChangeCodeLenses: this.onDidChangeLensesEmitter.event,
        provideCodeLenses: (document) => this.lensesFor(document),
      }),
    );
  }

  get activeWorkflowId(): string | undefined {
    return this.state?.workflowId;
  }

  show(workflowId: string, summary: DiffSummary): void {
    this.state = { workflowId, summary, dismissed: new Set() };
    this.render();
    void vscode.commands.executeCommand("setContext", "jarvis.ghostActive", true);
  }

  clear(): void {
    this.state = undefined;
    for (const editor of vscode.window.visibleTextEditors) {
      editor.setDecorations(this.addedDecoration, []);
      editor.setDecorations(this.removedDecoration, []);
    }
    this.onDidChangeLensesEmitter.fire();
    void vscode.commands.executeCommand("setContext", "jarvis.ghostActive", false);
  }

  private fileFor(document: vscode.TextDocument): DiffFile | undefined {
    if (!this.state || document.uri.scheme !== "file") return undefined;
    return findDiffFile(this.state.summary, document.uri.fsPath);
  }

  private render(): void {
    for (const editor of vscode.window.visibleTextEditors) {
      const file = this.fileFor(editor.document);
      if (!file) {
        editor.setDecorations(this.addedDecoration, []);
        editor.setDecorations(this.removedDecoration, []);
        continue;
      }
      const added: vscode.DecorationOptions[] = [];
      const removed: vscode.DecorationOptions[] = [];
      file.hunks.forEach((hunk, index) => {
        if (this.state?.dismissed.has(hunkKey(editor.document.uri, index))) return;
        const target = hunk.added > 0 ? added : removed;
        const hover = this.hover(file, hunk);
        for (const range of ghostRanges(editor.document, hunk)) {
          target.push({ range, hoverMessage: hover });
        }
      });
      editor.setDecorations(this.addedDecoration, added);
      editor.setDecorations(this.removedDecoration, removed);
    }
    this.onDidChangeLensesEmitter.fire();
  }

  private hover(file: DiffFile, hunk: DiffHunk): vscode.MarkdownString {
    const md = new vscode.MarkdownString();
    md.appendMarkdown(`**Jarvis proposes** · \`${file.path}\` · +${hunk.added} −${hunk.removed}\n\n`);
    if (hunk.removedText.length > 0) {
      md.appendCodeblock(hunk.removedText.map((l) => `- ${l}`).join("\n"), "diff");
    }
    if (hunk.addedText.length > 0) {
      md.appendCodeblock(hunk.addedText.map((l) => `+ ${l}`).join("\n"), "diff");
    }
    return md;
  }

  private lensesFor(document: vscode.TextDocument): vscode.CodeLens[] {
    const file = this.fileFor(document);
    if (!file || !this.state) return [];
    const lenses: vscode.CodeLens[] = [];
    file.hunks.forEach((hunk, index) => {
      if (this.state?.dismissed.has(hunkKey(document.uri, index))) return;
      const anchor = addedRuns(hunk)[0]?.startLine ?? hunkRange(hunk).startLine;
      const line = Math.min(Math.max(anchor - 1, 0), document.lineCount - 1);
      const range = new vscode.Range(line, 0, line, 0);
      const args = [{ uri: document.uri.toString(), hunkIndex: index, path: file.path }];
      lenses.push(
        new vscode.CodeLens(range, {
          title: `$(check) Accept  +${hunk.added} −${hunk.removed}`,
          command: "jarvis.ghost.accept",
          arguments: args,
        }),
        new vscode.CodeLens(range, {
          title: "$(x) Reject",
          command: "jarvis.ghost.reject",
          arguments: args,
        }),
        new vscode.CodeLens(range, {
          title: "$(info) Why",
          command: "jarvis.ghost.why",
          arguments: args,
        }),
      );
    });
    return lenses;
  }

  private resolve(arg: unknown): { document: vscode.TextDocument; file: DiffFile; hunk: DiffHunk; index: number } | undefined {
    if (!this.state || typeof arg !== "object" || arg === null) return undefined;
    const { uri, hunkIndex } = arg as { uri?: string; hunkIndex?: number };
    if (typeof uri !== "string" || typeof hunkIndex !== "number") return undefined;
    const parsed = vscode.Uri.parse(uri);
    const document = vscode.workspace.textDocuments.find((d) => d.uri.toString() === uri);
    if (!document) return undefined;
    const file = findDiffFile(this.state.summary, parsed.fsPath);
    const hunk = file?.hunks[hunkIndex];
    if (!file || !hunk) return undefined;
    return { document, file, hunk, index: hunkIndex };
  }

  /**
   * Applies the hunk to the open buffer. The old lines come from the patch's
   * `-` side, so we only replace when the buffer actually still holds them —
   * a drifted file gets an honest warning instead of a mangled edit.
   */
  async accept(arg: unknown): Promise<void> {
    const resolved = this.resolve(arg);
    if (!resolved) return;
    const { document, hunk, index } = resolved;

    const start = Math.max(hunk.oldStart - 1, 0);
    const end = Math.min(start + hunk.oldLines, document.lineCount);
    if (start >= document.lineCount) {
      void vscode.window.showWarningMessage(
        "Jarvis: this file has moved past the proposed hunk. Open the full diff instead.",
      );
      return;
    }
    const current = document.getText(new vscode.Range(start, 0, end, 0)).replace(/\r?\n$/, "");
    const expected = hunk.removedText.join("\n");
    if (hunk.removedText.length > 0 && current.trim() !== expected.trim()) {
      const choice = await vscode.window.showWarningMessage(
        "Jarvis: the open file no longer matches what the agent changed. Apply anyway?",
        { modal: true },
        "Apply anyway",
      );
      if (choice !== "Apply anyway") return;
    }

    const replacement = hunk.addedText.length > 0 ? `${hunk.addedText.join("\n")}\n` : "";
    const edit = new vscode.WorkspaceEdit();
    edit.replace(document.uri, new vscode.Range(start, 0, end, 0), replacement);
    const applied = await vscode.workspace.applyEdit(edit);
    if (!applied) {
      void vscode.window.showErrorMessage("Jarvis: could not apply the hunk.");
      return;
    }
    this.state?.dismissed.add(hunkKey(document.uri, index));
    this.render();
  }

  /** Dismisses the ghost and offers to turn it into a repair directive. */
  async reject(arg: unknown): Promise<void> {
    const resolved = this.resolve(arg);
    if (!resolved) return;
    const { document, file, hunk, index } = resolved;
    this.state?.dismissed.add(hunkKey(document.uri, index));
    this.render();

    const what = await vscode.window.showInputBox({
      title: `Jarvis · repair ${file.path}:${hunkRange(hunk).startLine}`,
      prompt: "What should Jarvis do differently here? (Esc just dismisses the ghost.)",
      placeHolder: "e.g. keep the existing error handling and add the endpoint below it",
      ignoreFocusOut: true,
    });
    if (!what?.trim()) return;
    await this.seedIntent(
      `Repair ${file.path}:${hunkRange(hunk).startLine} — ${what.trim()}`,
    );
  }

  /**
   * "Why" for a hunk: the goal it serves, its acceptance criteria and how the
   * evidence graded them, plus the reviewer's verdict.
   *
   * The daemon publishes no per-step plan text (`PlanCreated.v1` carries only
   * the state transition), so this is the real, sourced answer rather than a
   * fabricated step list.
   */
  async why(arg: unknown): Promise<void> {
    const resolved = this.resolve(arg);
    if (!resolved || !this.state) return;
    const { file, hunk } = resolved;
    const workflowId = this.state.workflowId;

    const workflow = this.store.snapshot.workflows.find((w) => w.id === workflowId);
    const goal = this.store.snapshot.goals.find((g) => g.id === workflow?.goalId);
    const manifest = await this.client.evidence(workflowId).catch(() => null);

    const lines: string[] = [
      `# Why · \`${file.path}\`:${hunkRange(hunk).startLine}`,
      "",
      `Workflow \`${workflowId.slice(-8)}\`${workflow?.branchName ? ` · branch \`${workflow.branchName}\`` : ""}`,
      "",
      "## The goal this serves",
      "",
      goal?.objective ?? goal?.title ?? "_The goal is no longer in the daemon's working set._",
      "",
    ];

    const criteria = goal?.acceptanceCriteria ?? [];
    if (criteria.length > 0) {
      lines.push("## Acceptance criteria", "");
      for (const c of criteria) lines.push(`- ${c}`);
      lines.push("");
    }

    const graded = manifest?.acceptanceCriteria ?? [];
    if (graded.length > 0) {
      lines.push("## How the evidence graded them", "");
      for (const c of graded) {
        lines.push(`- **${c.status}** — ${c.criterion}${c.note ? ` _(${c.note})_` : ""}`);
      }
      lines.push("");
    }

    const review = (manifest?.items ?? []).find((i) => i.kind === "report");
    if (review) {
      lines.push("## Independent review", "", `${review.title}`, "");
      if (review.summary) lines.push(`> ${review.summary}`, "");
    }

    lines.push(
      "## The hunk",
      "",
      "```diff",
      ...hunk.removedText.map((l) => `-${l}`),
      ...hunk.addedText.map((l) => `+${l}`),
      "```",
      "",
      "_Jarvis publishes no per-step plan text; this is what the goal contract and the sealed evidence actually record._",
    );

    const doc = await vscode.workspace.openTextDocument({
      content: `${lines.join("\n")}\n`,
      language: "markdown",
    });
    await vscode.window.showTextDocument(doc, { preview: true, viewColumn: vscode.ViewColumn.Beside });
  }

  dispose(): void {
    this.addedDecoration.dispose();
    this.removedDecoration.dispose();
    for (const d of this.disposables) d.dispose();
  }
}
