// HTTP client for the local Jarvis daemon. Runs in the VS Code Node extension
// host; uses global fetch (Node 18+). No `vscode` import — unit/smoke testable.

import { probeDaemonHealth, type DaemonHealth } from "./daemonHealth";
import type { RoutingDecision } from "./lens/routing";
import type {
  AgentInfo,
  ApprovalRequest,
  CostSummary,
  CreateGoalRequest,
  DaemonStatus,
  EventEnvelope,
  EvidenceManifest,
  GoalContract,
  ProjectDescriptor,
  WorkflowSummary,
} from "./model";

export class DaemonUnreachableError extends Error {
  constructor(cause: unknown) {
    super(`Jarvis daemon is not reachable: ${cause instanceof Error ? cause.message : String(cause)}`);
    this.name = "DaemonUnreachableError";
  }
}

export class DaemonClient {
  constructor(private readonly baseUrl: string) {}

  private url(path: string): string {
    return `${this.baseUrl.replace(/\/$/, "")}${path}`;
  }

  private async getJson<T>(path: string, signal?: AbortSignal): Promise<T> {
    let response: Response;
    try {
      response = await fetch(this.url(path), { signal });
    } catch (cause) {
      throw new DaemonUnreachableError(cause);
    }
    if (!response.ok) {
      throw new Error(`GET ${path} → ${response.status}`);
    }
    return (await response.json()) as T;
  }

  private async postJson<T>(path: string, body?: unknown): Promise<T> {
    let response: Response;
    try {
      response = await fetch(this.url(path), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
    } catch (cause) {
      throw new DaemonUnreachableError(cause);
    }
    if (!response.ok) {
      throw new Error(`POST ${path} → ${response.status}: ${await response.text().catch(() => "")}`);
    }
    const text = await response.text();
    return (text ? JSON.parse(text) : undefined) as T;
  }

  /** Health probe (`/healthz`, falling back to `/api/v1/status`). Never throws. */
  health(signal?: AbortSignal): Promise<DaemonHealth> {
    return probeDaemonHealth(this.baseUrl, signal ? { signal } : {});
  }

  async isReachable(signal?: AbortSignal): Promise<boolean> {
    return (await this.health(signal)).online;
  }

  status(signal?: AbortSignal): Promise<DaemonStatus> {
    return this.getJson<DaemonStatus>("/api/v1/status", signal);
  }

  projects(signal?: AbortSignal): Promise<ProjectDescriptor[]> {
    return this.getJson<ProjectDescriptor[]>("/api/v1/projects", signal);
  }

  goals(projectId: string, signal?: AbortSignal): Promise<GoalContract[]> {
    return this.getJson<GoalContract[]>(`/api/v1/goals?project=${encodeURIComponent(projectId)}`, signal);
  }

  workflows(signal?: AbortSignal): Promise<WorkflowSummary[]> {
    return this.getJson<WorkflowSummary[]>("/api/v1/workflows", signal);
  }

  approvals(signal?: AbortSignal): Promise<ApprovalRequest[]> {
    return this.getJson<ApprovalRequest[]>("/api/v1/approvals", signal);
  }

  agents(signal?: AbortSignal): Promise<AgentInfo[]> {
    return this.getJson<AgentInfo[]>("/api/v1/agents", signal);
  }

  costs(signal?: AbortSignal): Promise<CostSummary> {
    return this.getJson<CostSummary>("/api/v1/costs", signal);
  }

  /**
   * The Model Council's route for a directive, without running anything. This
   * is what the Intent Bar previews live as you type: `explain` is a pure
   * query — it records a decision id but engages no agent and spends nothing.
   *
   * `fast` skips the local-model second opinion and answers from the heuristic
   * classifier alone — ~6-8 ms of daemon work against 0.14-0.22 s warm and up
   * to ~1.5 s cold. It is the same policy over a cheaper classification, so it
   * can disagree with the full answer; anything rendered from it must say so.
   */
  explainRoute(
    directive: string,
    options: { role?: string; projectId?: string; localOnly?: boolean; fast?: boolean } = {},
    signal?: AbortSignal,
  ): Promise<RoutingDecision> {
    const params = new URLSearchParams({ directive, role: options.role ?? "implementer" });
    if (options.projectId) params.set("projectId", options.projectId);
    if (options.localOnly) params.set("localOnly", "true");
    if (options.fast) params.set("fast", "true");
    return this.getJson<RoutingDecision>(`/api/v1/routing/explain?${params.toString()}`, signal);
  }

  /** Long-poll event feed. Returns events after the cursor, waiting up to waitSeconds. */
  events(after: number, waitSeconds: number, signal?: AbortSignal): Promise<EventEnvelope[]> {
    return this.getJson<EventEnvelope[]>(
      `/api/v1/events?after=${after}&waitSeconds=${waitSeconds}&max=500`,
      signal,
    );
  }

  /** Latest evidence manifest for a workflow; null when none has been published. */
  async evidence(workflowId: string, signal?: AbortSignal): Promise<EvidenceManifest | null> {
    try {
      return await this.getJson<EvidenceManifest>(`/api/v1/workflows/${workflowId}/evidence`, signal);
    } catch (cause) {
      if (cause instanceof DaemonUnreachableError) throw cause;
      return null;
    }
  }

  async diff(workflowId: string): Promise<string | null> {
    try {
      const r = await fetch(this.url(`/api/v1/workflows/${workflowId}/diff`));
      return r.ok ? await r.text() : null;
    } catch (cause) {
      throw new DaemonUnreachableError(cause);
    }
  }

  registerProject(path: string, name?: string): Promise<ProjectDescriptor> {
    return this.postJson<ProjectDescriptor>("/api/v1/projects", { path, name });
  }

  createGoal(request: CreateGoalRequest): Promise<GoalContract> {
    return this.postJson<GoalContract>("/api/v1/goals", request);
  }

  runGoal(goalId: string): Promise<WorkflowSummary> {
    return this.postJson<WorkflowSummary>(`/api/v1/goals/${goalId}/run`);
  }

  cancelWorkflow(workflowId: string): Promise<void> {
    return this.postJson<void>(`/api/v1/workflows/${workflowId}/cancel`);
  }

  resolveApproval(
    approvalId: string,
    approved: boolean,
    actorId: string,
    note?: string,
  ): Promise<void> {
    return this.postJson<void>(`/api/v1/approvals/${approvalId}`, {
      approvalId,
      actor: { type: "user", id: actorId },
      approved,
      note,
      respondedAt: new Date().toISOString(),
    });
  }
}
