// Unified-diff parsing for the inline ghost diffs and the decision sheet's
// change summary. Pure: no `vscode` import, no filesystem. Unit-tested.
//
// The patch comes from the daemon's evidence artifact (`GET
// /api/v1/workflows/{id}/diff`), which is `git diff` output from the agent's
// worktree. Agent claims are never used — this is the same rule the control
// plane follows (see CLAUDE.md).

export interface DiffHunk {
  /** 1-based first line of the hunk in the NEW file. */
  newStart: number;
  newLines: number;
  oldStart: number;
  oldLines: number;
  added: number;
  removed: number;
  /** Text after the `@@ ... @@` marker — git's function-context hint. */
  context: string;
  /** The `+` lines, in order, for the ghost-block hover. */
  addedText: string[];
  /** The `-` lines, in order, for the ghost-block hover. */
  removedText: string[];
  /**
   * 1-based line numbers, in the NEW file, that the hunk actually adds.
   *
   * A hunk spans its context too — `git diff` emits three unchanged lines on
   * each side — so decorating `newStart..newStart+newLines` paints six lines of
   * untouched code as "proposed". These are the lines that really changed.
   */
  addedLines: number[];
}

export interface DiffFile {
  /** Repo-relative path in the new tree ("b/" side), forward slashes. */
  path: string;
  /** Repo-relative path in the old tree; differs on a rename. */
  oldPath: string;
  status: "added" | "modified" | "deleted" | "renamed";
  added: number;
  removed: number;
  hunks: DiffHunk[];
}

export interface DiffSummary {
  files: DiffFile[];
  filesChanged: number;
  added: number;
  removed: number;
}

const FILE_HEADER = /^diff --git a\/(.+?) b\/(.+)$/;
const HUNK_HEADER = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@ ?(.*)$/;

function stripPrefix(path: string): string {
  return path.replace(/^[ab]\//, "");
}

/**
 * Parses `git diff` output. Tolerant by design: a truncated or unusual patch
 * yields fewer files rather than throwing, because this runs on data that
 * crossed a process boundary and the UI must still render.
 */
export function parseUnifiedDiff(patch: string): DiffSummary {
  const files: DiffFile[] = [];
  let file: DiffFile | undefined;
  let hunk: DiffHunk | undefined;
  // Line cursor in the NEW file: context and `+` advance it, `-` does not.
  let newLine = 0;

  const pushHunk = (): void => {
    if (file && hunk) file.hunks.push(hunk);
    hunk = undefined;
  };
  const pushFile = (): void => {
    pushHunk();
    if (file) files.push(file);
    file = undefined;
  };

  for (const raw of patch.split(/\r?\n/)) {
    const header = FILE_HEADER.exec(raw);
    if (header) {
      pushFile();
      file = {
        path: stripPrefix(header[2]),
        oldPath: stripPrefix(header[1]),
        status: header[1] === header[2] ? "modified" : "renamed",
        added: 0,
        removed: 0,
        hunks: [],
      };
      continue;
    }
    if (!file) continue;

    if (raw.startsWith("new file mode")) {
      file.status = "added";
      continue;
    }
    if (raw.startsWith("deleted file mode")) {
      file.status = "deleted";
      continue;
    }
    if (raw.startsWith("rename to ")) {
      file.path = stripPrefix(raw.slice("rename to ".length).trim());
      file.status = "renamed";
      continue;
    }
    if (raw.startsWith("+++ ")) {
      const target = raw.slice(4).trim();
      if (target !== "/dev/null") file.path = stripPrefix(target);
      continue;
    }

    const hunkHeader = HUNK_HEADER.exec(raw);
    if (hunkHeader) {
      pushHunk();
      hunk = {
        oldStart: Number(hunkHeader[1]),
        oldLines: hunkHeader[2] === undefined ? 1 : Number(hunkHeader[2]),
        newStart: Number(hunkHeader[3]),
        newLines: hunkHeader[4] === undefined ? 1 : Number(hunkHeader[4]),
        added: 0,
        removed: 0,
        context: hunkHeader[5] ?? "",
        addedText: [],
        removedText: [],
        addedLines: [],
      };
      newLine = hunk.newStart;
      continue;
    }

    if (!hunk) continue;
    if (raw.startsWith("+")) {
      hunk.added += 1;
      file.added += 1;
      hunk.addedText.push(raw.slice(1));
      hunk.addedLines.push(newLine);
      newLine += 1;
    } else if (raw.startsWith("-")) {
      hunk.removed += 1;
      file.removed += 1;
      hunk.removedText.push(raw.slice(1));
    } else if (raw.startsWith(" ") || raw === "") {
      newLine += 1;
    }
  }
  pushFile();

  return {
    files,
    filesChanged: files.length,
    added: files.reduce((n, f) => n + f.added, 0),
    removed: files.reduce((n, f) => n + f.removed, 0),
  };
}

/**
 * The contiguous runs of added lines in a hunk, 1-based and inclusive, in the
 * new file's coordinates. This is what a ghost block should paint: the lines
 * the agent actually wrote, not the context git printed around them.
 */
export function addedRuns(hunk: DiffHunk): { startLine: number; endLine: number }[] {
  const runs: { startLine: number; endLine: number }[] = [];
  for (const line of hunk.addedLines) {
    const last = runs[runs.length - 1];
    if (last && line === last.endLine + 1) last.endLine = line;
    else runs.push({ startLine: line, endLine: line });
  }
  return runs;
}

/**
 * The range a hunk occupies in the OPEN document, 1-based and inclusive.
 * A pure-deletion hunk has no new lines, so it collapses onto the line the
 * deletion sits above — decorate that one line rather than nothing.
 */
export function hunkRange(hunk: DiffHunk): { startLine: number; endLine: number } {
  if (hunk.newLines <= 0) {
    const line = Math.max(1, hunk.newStart);
    return { startLine: line, endLine: line };
  }
  return { startLine: hunk.newStart, endLine: hunk.newStart + hunk.newLines - 1 };
}

/**
 * Finds the diff entry for an open file.
 *
 * The patch is worktree-relative and the editor path is absolute, so match on
 * the longest path suffix. Windows paths arrive with backslashes, and git
 * always emits forward slashes, so both sides are normalized. Matching on a
 * *segment* boundary matters: `src/App.ts` must not match `vendor/src/App.ts`'s
 * sibling `OtherApp.ts`, and a bare basename match would pair the wrong file in
 * any repo with two `index.ts`.
 */
export function findDiffFile(summary: DiffSummary, absolutePath: string): DiffFile | undefined {
  const normalized = absolutePath.replace(/\\/g, "/").toLowerCase();
  let best: DiffFile | undefined;
  let bestLength = 0;
  for (const file of summary.files) {
    if (file.status === "deleted") continue;
    const candidate = file.path.toLowerCase();
    if (normalized === candidate || normalized.endsWith(`/${candidate}`)) {
      if (candidate.length > bestLength) {
        best = file;
        bestLength = candidate.length;
      }
    }
  }
  return best;
}

/** "3 files · +42 −7" — the decision sheet's one-line change summary. */
export function describeDiff(summary: DiffSummary): string {
  if (summary.filesChanged === 0) return "no file changes";
  const files = `${summary.filesChanged} file${summary.filesChanged === 1 ? "" : "s"}`;
  return `${files} · +${summary.added} −${summary.removed}`;
}
