// Wire shape of the Model Council's routing decision (`GET /api/v1/routing/explain`)
// plus the pure mapping that turns it into the Intent Bar's live preview.
//
// No `vscode` import: this module is unit-tested outside the extension host.

import { localModelVerdict, routeFingerprint, type LocalModelVerdict } from "./routeSignals";

/** Subset of Jarvis.Contracts' RoutingDecision that the Lens actually renders. */
export interface RoutingClassification {
  class?: string;
  source?: string;
  confidence?: number;
  risk?: string;
  mutation?: string;
  latency?: string;
  evidence?: string;
  data?: string;
  requiredCapabilities?: string[] | null;
  signals?: string[] | null;
}

export interface RoutingSelection {
  adapterId?: string;
  harness?: string;
  vendor?: string;
  modelFamily?: string;
  model?: string | null;
  tier?: string;
  mode?: string;
  runtime?: string | null;
  sandbox?: string;
  estimatedCostUsd?: number | null;
  costBasis?: string;
  canImplement?: boolean;
}

export interface RoutingDecision {
  id?: string;
  role?: string;
  policyVersion?: string;
  classification?: RoutingClassification | null;
  selected?: RoutingSelection | null;
  estimatedCostUsd?: number | null;
  estimateBasis?: string;
  /** Wire-deserialized collections can arrive null — normalize before use. */
  rationale?: string[] | null;
  rejectedAlternatives?: unknown[] | null;
  independence?: string;
}

export interface PreviewChip {
  /** Stable id so the webview can key/animate chips instead of re-creating them. */
  id: string;
  label: string;
  value: string;
  tone: "neutral" | "accent" | "ok" | "warn" | "danger";
}

export interface RoutePreview {
  headline: string;
  chips: PreviewChip[];
  agentId: string;
  model: string;
  tier: string;
  mode: string;
  localOnly: boolean;
  costUsd: number | null;
  costLabel: string;
  etaLabel: string;
  rationale: string[];
  signals: string[];
  /** `heuristic` or `local-model` — which classifier produced this. */
  source: string;
  /** The local model's second opinion, when it gave one. Never present on a fast preview. */
  localModel: LocalModelVerdict | null;
  /** Everything on screen, flattened: two previews with the same one look alike. */
  fingerprint: string;
}

const TITLE_CASE: Record<string, string> = {
  trivial: "Trivial change",
  standard: "Standard change",
  complex: "Complex change",
  risky: "Risky change",
  research: "Research",
  review: "Review",
};

/** Rough wall-clock expectation per task class — labelled "~" because it is. */
const ETA_MINUTES: Record<string, number> = {
  trivial: 2,
  standard: 6,
  complex: 18,
  risky: 22,
  research: 10,
  review: 4,
};

export function formatCost(value: number | null | undefined): string {
  if (value === null || value === undefined || !Number.isFinite(value)) return "cost n/a";
  if (value === 0) return "free";
  if (value < 0.01) return "<$0.01";
  return `~$${value.toFixed(2)}`;
}

function titleCase(value: string): string {
  if (!value) return value;
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function riskTone(risk: string): PreviewChip["tone"] {
  switch (risk.toLowerCase()) {
    case "high":
    case "critical":
      return "danger";
    case "medium":
      return "warn";
    case "low":
      return "ok";
    default:
      return "neutral";
  }
}

/**
 * Maps a council decision onto the chips the Intent Bar shows while you type.
 * Everything is defensive: `/routing/explain` is a live endpoint and a partial
 * decision must still render rather than blank the preview.
 */
export function toRoutePreview(decision: RoutingDecision): RoutePreview {
  const classification = decision.classification ?? {};
  const selected = decision.selected ?? {};

  const taskClass = (classification.class ?? "standard").toLowerCase();
  const risk = classification.risk ?? "low";
  const agentId = selected.adapterId ?? "unrouted";
  const model = selected.model ?? selected.modelFamily ?? "adapter default";
  const tier = titleCase(selected.tier ?? "unknown");
  const mode = (selected.mode ?? "cloud").toLowerCase();
  const localOnly = mode === "local" || (classification.data ?? "").toLowerCase() === "localonly";
  const cost = decision.estimatedCostUsd ?? selected.estimatedCostUsd ?? null;
  const costLabel = formatCost(cost);
  const eta = ETA_MINUTES[taskClass] ?? 6;
  const etaLabel = `~${eta} min`;

  const chips: PreviewChip[] = [
    {
      id: "class",
      label: "shape",
      value: TITLE_CASE[taskClass] ?? titleCase(taskClass),
      tone: "accent",
    },
    { id: "risk", label: "risk", value: titleCase(risk), tone: riskTone(risk) },
    { id: "agent", label: titleCase(decision.role ?? "implementer"), value: agentId, tone: "neutral" },
    { id: "model", label: tier, value: model, tone: "neutral" },
    { id: "cost", label: "cost", value: costLabel, tone: cost !== null && cost > 1 ? "warn" : "neutral" },
    { id: "eta", label: "time", value: etaLabel, tone: "neutral" },
    {
      id: "locality",
      label: "runs",
      value: localOnly ? "on this machine" : "in the cloud",
      tone: localOnly ? "ok" : "neutral",
    },
  ];

  const headline = `${TITLE_CASE[taskClass] ?? titleCase(taskClass)} · ${agentId} ${
    (decision.role ?? "implements").toLowerCase() === "reviewer" ? "reviews" : "implements"
  } · ${costLabel} · ${etaLabel}`;

  return {
    headline,
    chips,
    agentId,
    model,
    tier,
    mode,
    localOnly,
    costUsd: cost,
    costLabel,
    etaLabel,
    rationale: decision.rationale ?? [],
    signals: classification.signals ?? [],
    source: classification.source ?? "heuristic",
    localModel: localModelVerdict(decision),
    fingerprint: routeFingerprint(decision),
  };
}
