import * as vscode from "vscode";
import { pillStateFor, type Capsule } from "./capsule";
import type { Snapshot, Store } from "../store";

/**
 * Drives the Lens pill — the floating glass capsule the fork renders over the
 * editor area (apps/forge-vscode/patches/0005-lens-pill.patch).
 *
 * The workbench cannot see extension state, so the extension publishes it as
 * context keys and the core contribution reads them. Context keys are the one
 * channel that already crosses that boundary in both directions, which keeps
 * the core patch to "render what these four keys say" with no new IPC.
 */
export class LensPill implements vscode.Disposable {
  private readonly disposables: vscode.Disposable[] = [];
  private last = "";

  constructor(
    store: Store,
    private readonly capsulesOf: () => Capsule[],
  ) {
    this.render(store.snapshot);
    this.disposables.push(store.onDidChange((snap) => this.render(snap)));
  }

  private render(snap: Snapshot): void {
    const pill = pillStateFor(snap.online, this.capsulesOf(), snap.approvals.length);
    const signature = `${pill.state}|${pill.label}|${pill.detail}|${pill.progress}`;
    // setContext round-trips to the renderer; skip the no-op writes the 4s poll
    // would otherwise produce forever.
    if (signature === this.last) return;
    this.last = signature;

    void vscode.commands.executeCommand("setContext", "jarvis.lens.state", pill.state);
    void vscode.commands.executeCommand("setContext", "jarvis.lens.label", pill.label);
    void vscode.commands.executeCommand("setContext", "jarvis.lens.detail", pill.detail);
    void vscode.commands.executeCommand("setContext", "jarvis.lens.progress", pill.progress);
  }

  dispose(): void {
    for (const d of this.disposables) d.dispose();
    void vscode.commands.executeCommand("setContext", "jarvis.lens.state", "offline");
  }
}
