// Wire shapes from Jarvis.Contracts (camelCase, string enums). No `vscode`
// import here so this module stays unit-testable outside the extension host.

export interface DaemonStatus {
  version: string;
  uptimeSeconds: number;
  dataRoot?: string;
  projectCount: number;
  activeWorkflowCount: number;
  pendingApprovalCount: number;
  lastEventSequence: number;
}

export interface ProjectDescriptor {
  id: string;
  name: string;
  rootPath: string;
  defaultBranch: string;
  buildProfile?: { kind: string };
}

export interface GoalContract {
  id: string;
  projectId: string;
  title: string;
  status: string;
  objective?: string;
  /** Wire-deserialized collections can arrive null — normalize before use. */
  acceptanceCriteria?: string[] | null;
}

export interface WorkflowSummary {
  id: string;
  goalId: string;
  projectId: string;
  state: string;
  branchName?: string;
  baselineCommit?: string;
  createdAt: string;
  completedAt?: string;
  failureReason?: string;
}

export interface ApprovalRequest {
  id: string;
  decisionId: string;
  workflowId?: string;
  summary: string;
  risk: string;
  requestedAt: string;
}

export interface AgentInfo {
  id: string;
  available: boolean;
  sessions: number;
  completedSessions: number;
  totalCostUsd: number;
}

export interface CostSummary {
  agentSessions: number;
  inputTokens: number;
  outputTokens: number;
  totalCostUsd: number;
}

export interface EvidenceArtifact {
  id: string;
  sha256: string;
  contentType?: string;
  sizeBytes?: number;
  classification?: string;
}

export interface EvidenceItem {
  id: string;
  kind: string;
  title: string;
  outcome: string;
  summary?: string;
  artifact?: EvidenceArtifact | null;
}

export interface AcceptanceCriterionResult {
  criterion: string;
  status: string;
  evidenceItemIds?: string[] | null;
  note?: string | null;
}

export interface EvidenceManifest {
  id: string;
  workflowId: string;
  createdAt: string;
  /** Wire-deserialized collections can arrive null — normalize before use. */
  items?: EvidenceItem[] | null;
  acceptanceCriteria?: AcceptanceCriterionResult[] | null;
  manifestHash?: string;
}

export interface EventEnvelope {
  eventId: string;
  eventType: string;
  occurredAt: string;
  correlationId: string;
  sequence: number;
  data?: Record<string, unknown>;
}

export interface CreateGoalRequest {
  project: string;
  title: string;
  objective?: string;
  agent?: string;
  skipPlanning?: boolean;
}

export const TERMINAL_STATES: ReadonlySet<string> = new Set([
  "completed",
  "discarded",
  "failed",
  "cancelled",
]);

export function isActiveWorkflow(w: WorkflowSummary): boolean {
  return !TERMINAL_STATES.has(w.state);
}
