import * as vscode from "vscode";
import { DaemonClient } from "./daemonClient";
import { applyEvents, factsFor, type FactsMap } from "./lens/facts";
import type {
  AgentInfo,
  ApprovalRequest,
  CostSummary,
  DaemonStatus,
  EventEnvelope,
  GoalContract,
  ProjectDescriptor,
  WorkflowSummary,
} from "./model";
import type { WorkflowFacts } from "./lens/capsule";

/** Snapshot of daemon state shared by the Lens, the tree views and the status bar. */
export interface Snapshot {
  online: boolean;
  /** A daemon launch is in flight (jarvis.startDaemon waiting on the health probe). */
  connecting: boolean;
  status: DaemonStatus | null;
  projects: ProjectDescriptor[];
  workflows: WorkflowSummary[];
  approvals: ApprovalRequest[];
  agents: AgentInfo[];
  /** Goals for the workspace project only — enough to title the capsules. */
  goals: GoalContract[];
  costs: CostSummary | null;
}

const EMPTY: Snapshot = {
  online: false,
  connecting: false,
  status: null,
  projects: [],
  workflows: [],
  approvals: [],
  agents: [],
  goals: [],
  costs: null,
};

function normalizePath(value: string): string {
  return value.replace(/\\/g, "/").replace(/\/+$/, "").toLowerCase();
}

/** Central polled state. Views subscribe to onDidChange and re-read `snapshot`. */
export class Store {
  private readonly emitter = new vscode.EventEmitter<Snapshot>();
  readonly onDidChange = this.emitter.event;
  private current: Snapshot = EMPTY;
  private readonly facts: FactsMap = {};

  constructor(readonly client: DaemonClient) {}

  get snapshot(): Snapshot {
    return this.current;
  }

  /**
   * The registered project whose root contains (or equals) the open folder.
   * Longest match wins so a nested project beats its parent.
   */
  get workspaceProject(): ProjectDescriptor | null {
    const folders = vscode.workspace.workspaceFolders ?? [];
    if (folders.length === 0) return null;
    let best: ProjectDescriptor | null = null;
    for (const folder of folders) {
      const open = normalizePath(folder.uri.fsPath);
      for (const project of this.current.projects) {
        const root = normalizePath(project.rootPath);
        if (open === root || open.startsWith(`${root}/`) || root.startsWith(`${open}/`)) {
          if (!best || root.length > normalizePath(best.rootPath).length) best = project;
        }
      }
    }
    return best;
  }

  factsOf(workflowId: string): WorkflowFacts {
    return factsFor(this.facts, workflowId);
  }

  /** Folds the event batch into the per-workflow facts. True when a redraw is warranted. */
  ingestEvents(events: readonly EventEnvelope[]): boolean {
    return applyEvents(this.facts, events);
  }

  async refresh(): Promise<void> {
    try {
      const [status, projects, workflows, approvals, agents, costs] = await Promise.all([
        this.client.status(),
        this.client.projects(),
        this.client.workflows(),
        this.client.approvals(),
        this.client.agents(),
        this.client.costs().catch(() => null),
      ]);
      this.current = {
        online: true,
        connecting: false,
        status,
        projects,
        workflows,
        approvals,
        agents,
        goals: this.current.goals,
        costs,
      };
      // Goals need the project, which we only just learned — resolve against the
      // snapshot we are about to publish rather than the previous one.
      const project = this.workspaceProject;
      this.current = {
        ...this.current,
        goals: project ? await this.client.goals(project.id).catch(() => []) : [],
      };
    } catch {
      this.current = { ...EMPTY, online: false, connecting: this.current.connecting };
    }
    this.emitter.fire(this.current);
  }

  /** Re-publishes the current snapshot without hitting the daemon. */
  touch(): void {
    this.emitter.fire(this.current);
  }

  /** Marks a daemon launch as in flight so the status bar can show it. */
  setConnecting(connecting: boolean): void {
    if (this.current.connecting === connecting) return;
    this.current = { ...this.current, connecting };
    this.emitter.fire(this.current);
  }

  dispose(): void {
    this.emitter.dispose();
  }
}
