import * as vscode from "vscode";
import { isActiveWorkflow, type WorkflowSummary } from "../model";
import { workflowDescription, workflowIcon } from "../presentation";
import type { Store } from "../store";

export class WorkflowItem extends vscode.TreeItem {
  constructor(readonly workflow: WorkflowSummary) {
    super(shortId(workflow), vscode.TreeItemCollapsibleState.None);
    this.description = workflowDescription(workflow);
    this.tooltip = buildTooltip(workflow);
    const active = isActiveWorkflow(workflow);
    this.contextValue = active ? "jarvisWorkflowActive" : "jarvisWorkflowDone";
    const { icon, color } = workflowIcon(workflow.state);
    this.iconPath = new vscode.ThemeIcon(icon, color ? new vscode.ThemeColor(color) : undefined);
    this.id = `workflow:${workflow.id}`;
  }
}

export class WorkflowsView implements vscode.TreeDataProvider<vscode.TreeItem> {
  private readonly emitter = new vscode.EventEmitter<void>();
  readonly onDidChangeTreeData = this.emitter.event;

  constructor(private readonly store: Store) {
    store.onDidChange(() => this.emitter.fire());
  }

  getTreeItem(element: vscode.TreeItem): vscode.TreeItem {
    return element;
  }

  getChildren(): vscode.TreeItem[] {
    const snap = this.store.snapshot;
    if (!snap.online) {
      const item = new vscode.TreeItem("Daemon offline", vscode.TreeItemCollapsibleState.None);
      item.iconPath = new vscode.ThemeIcon("debug-disconnect");
      return [item];
    }
    if (snap.workflows.length === 0) {
      const item = new vscode.TreeItem("No workflows — engage a directive", vscode.TreeItemCollapsibleState.None);
      item.iconPath = new vscode.ThemeIcon("info");
      item.command = { command: "jarvis.engage", title: "Engage" };
      return [item];
    }
    // Active first (design: what needs attention rises), then most recent.
    const sorted = [...snap.workflows].sort((a, b) => {
      const activeDelta = Number(isActiveWorkflow(b)) - Number(isActiveWorkflow(a));
      return activeDelta !== 0 ? activeDelta : b.id.localeCompare(a.id);
    });
    return sorted.map((w) => new WorkflowItem(w));
  }
}

function shortId(w: WorkflowSummary): string {
  return `wf ${w.id.slice(-8)}`;
}

function buildTooltip(w: WorkflowSummary): string {
  const lines = [`Workflow ${w.id}`, `State: ${w.state}`];
  if (w.branchName) lines.push(`Branch: ${w.branchName}`);
  if (w.baselineCommit) lines.push(`Baseline: ${w.baselineCommit.slice(0, 10)}`);
  if (w.failureReason) lines.push(`Reason: ${w.failureReason}`);
  return lines.join("\n");
}
