// Evidence manifest -> the chips the Lens shows on an expanded capsule and on
// the decision sheet. Pure; unit-tested.

import type { EvidenceManifest } from "../model";
import type { EvidenceChip } from "./protocol";

const KIND_LABEL: Record<string, string> = {
  build: "build",
  test: "tests",
  lint: "lint",
  diff: "diff",
  report: "review",
  log: "log",
};

function normalizeOutcome(outcome: string): EvidenceChip["outcome"] {
  switch (outcome.toLowerCase()) {
    case "passed":
      return "passed";
    case "failed":
      return "failed";
    default:
      return "info";
  }
}

/**
 * Wire-deserialized contract types arrive with `null` collections when the JSON
 * omitted them (the STJ constructor path skips property initializers — see
 * CLAUDE.md), so every list is normalized before use.
 */
export function toEvidenceChips(manifest: EvidenceManifest | null): EvidenceChip[] {
  const items = manifest?.items ?? [];
  return items.map((item) => ({
    id: item.id,
    kind: item.kind,
    label: KIND_LABEL[item.kind.toLowerCase()] ?? item.kind,
    outcome: normalizeOutcome(item.outcome),
    detail: item.summary ?? item.title,
    hash: item.artifact ? item.artifact.sha256.slice(0, 12) : null,
  }));
}

export function toAcceptance(
  manifest: EvidenceManifest | null,
): { criterion: string; status: string; note: string | null }[] {
  return (manifest?.acceptanceCriteria ?? []).map((c) => ({
    criterion: c.criterion,
    status: c.status,
    note: c.note ?? null,
  }));
}

/**
 * The reviewer's identity as the evidence itself records it. The review item's
 * title is written by the daemon as "Independent review by <agent>: <verdict>",
 * so it is a second, independent source for the badge next to the event feed —
 * useful because the event pump can start after a workflow finished.
 */
export function reviewerFromEvidence(manifest: EvidenceManifest | null): string | null {
  for (const item of manifest?.items ?? []) {
    const match = /independent review by ([\w.-]+)/i.exec(item.title);
    if (match) return match[1];
  }
  return null;
}
