// The Flow River's capsule model: a workflow rendered as one glass capsule
// travelling the six stages Isolate - Plan - Build - Verify - Review - Approve.
//
// Pure: no `vscode` import, no fetch. Unit-tested in test/capsule.test.ts.

import { TERMINAL_STATES, type WorkflowSummary } from "../model";

export const LENS_STAGES = ["Isolate", "Plan", "Build", "Verify", "Review", "Approve"] as const;
export type LensStage = (typeof LENS_STAGES)[number];

/**
 * Workflow state -> the stage the capsule is *sitting in*. `planned` has not
 * entered the river yet, so it maps to -1 (queued at the mouth).
 */
const STATE_STAGE: Record<string, number> = {
  planned: -1,
  isolating: 0,
  planning: 1,
  executing: 2,
  verifying: 3,
  reviewing: 4,
  awaitingapproval: 5,
  completed: 6,
  failed: -2,
  cancelled: -2,
  discarded: -2,
};

export type CapsuleTone = "queued" | "running" | "attention" | "done" | "failed";

/** Per-workflow facts distilled from the event feed (agents, plan, repairs). */
export interface WorkflowFacts {
  implementer?: string;
  reviewer?: string;
  /** Agent ids seen on this workflow, in the order the router picked them. */
  agents: string[];
  planned: boolean;
  repairRounds: number;
  lastEventAt?: string;
  lastEventLabel?: string;
}

export const EMPTY_FACTS: WorkflowFacts = { agents: [], planned: false, repairRounds: 0 };

export interface CapsuleStage {
  name: LensStage;
  /** "done" | "active" | "pending" | "skipped" */
  status: "done" | "active" | "pending" | "skipped";
}

export interface Capsule {
  id: string;
  shortId: string;
  goalId: string;
  projectId: string;
  title: string;
  state: string;
  stateLabel: string;
  tone: CapsuleTone;
  stageIndex: number;
  stages: CapsuleStage[];
  progress: number;
  branch: string | null;
  createdAt: string;
  completedAt: string | null;
  failureReason: string | null;
  agents: string[];
  implementer: string | null;
  reviewer: string | null;
  independent: boolean;
  repairRounds: number;
  needsDecision: boolean;
  approvalId: string | null;
}

export function stageIndexFor(state: string): number {
  return STATE_STAGE[state.toLowerCase()] ?? -1;
}

export function toneFor(state: string): CapsuleTone {
  const lower = state.toLowerCase();
  if (lower === "awaitingapproval") return "attention";
  if (lower === "completed") return "done";
  if (lower === "planned") return "queued";
  if (TERMINAL_STATES.has(lower)) return "failed";
  return "running";
}

export function stateLabelFor(state: string): string {
  const words: Record<string, string> = {
    awaitingApproval: "Needs you",
    isolating: "Isolating",
    planning: "Planning",
    executing: "Building",
    verifying: "Verifying",
    reviewing: "Reviewing",
    completed: "Complete",
    discarded: "Discarded",
    cancelled: "Cancelled",
    failed: "Failed",
    planned: "Queued",
  };
  return words[state] ?? state.charAt(0).toUpperCase() + state.slice(1);
}

function stagesFor(stageIndex: number, tone: CapsuleTone): CapsuleStage[] {
  return LENS_STAGES.map((name, i) => {
    if (tone === "failed") {
      // A failed run froze somewhere: everything past the freeze is skipped, not pending.
      if (i < stageIndex) return { name, status: "done" as const };
      if (i === stageIndex) return { name, status: "active" as const };
      return { name, status: "skipped" as const };
    }
    if (stageIndex >= LENS_STAGES.length) return { name, status: "done" as const };
    if (i < stageIndex) return { name, status: "done" as const };
    if (i === stageIndex) return { name, status: "active" as const };
    return { name, status: "pending" as const };
  });
}

/** 0..100 fill of the capsule's stage ring. */
export function progressFor(state: string): number {
  const idx = stageIndexFor(state);
  if (state.toLowerCase() === "completed") return 100;
  if (idx < 0) return 0;
  return Math.round(((idx + 1) / LENS_STAGES.length) * 100);
}

export interface CapsuleInput {
  workflow: WorkflowSummary;
  title: string;
  facts?: WorkflowFacts;
  approvalId?: string | null;
}

export function toCapsule({ workflow, title, facts, approvalId }: CapsuleInput): Capsule {
  const f = facts ?? EMPTY_FACTS;
  const tone = toneFor(workflow.state);
  // A failed run has no stage of its own; show it frozen where it died. We do
  // not know that from `state` alone, so fall back to the last stage we have
  // evidence for: a reviewer means it reached Review, a plan means Build.
  let stageIndex = stageIndexFor(workflow.state);
  if (stageIndex === -2) {
    stageIndex = f.reviewer ? 4 : f.implementer ? 2 : f.planned ? 1 : 0;
  }

  const implementer = f.implementer ?? null;
  const reviewer = f.reviewer ?? null;

  return {
    id: workflow.id,
    shortId: workflow.id.slice(-8),
    goalId: workflow.goalId,
    projectId: workflow.projectId,
    title,
    state: workflow.state,
    stateLabel: stateLabelFor(workflow.state),
    tone,
    stageIndex,
    stages: stagesFor(stageIndex, tone),
    progress: progressFor(workflow.state),
    branch: workflow.branchName ?? null,
    createdAt: workflow.createdAt,
    completedAt: workflow.completedAt ?? null,
    failureReason: workflow.failureReason ?? null,
    agents: f.agents.length > 0 ? f.agents : [implementer, reviewer].filter((a): a is string => !!a),
    implementer,
    reviewer,
    independent: !!implementer && !!reviewer && implementer !== reviewer,
    repairRounds: f.repairRounds,
    // A pending approval is a decision whatever the workflow state says. The
    // integration approval parks the workflow in AwaitingApproval, but a
    // Sentinel escalation (an agent asking for `git.push`, say) can be pending
    // against a workflow that has already completed - and the human is just as
    // needed there.
    needsDecision: workflow.state === "awaitingApproval" || !!approvalId,
    approvalId: approvalId ?? null,
  };
}

/**
 * Newest first, but anything that needs a human decision floats to the top —
 * the Lens is a decision surface before it is a history.
 */
export function sortCapsules(capsules: Capsule[]): Capsule[] {
  const rank = (c: Capsule): number => {
    if (c.tone === "attention") return 0;
    if (c.tone === "running") return 1;
    if (c.tone === "queued") return 2;
    return 3;
  };
  return [...capsules].sort((a, b) => {
    const byRank = rank(a) - rank(b);
    if (byRank !== 0) return byRank;
    // Ids are ULIDs, so a plain string compare is a time compare.
    return a.id < b.id ? 1 : a.id > b.id ? -1 : 0;
  });
}

/** What the Lens pill should say, given the capsules on screen. */
export interface PillState {
  state: "offline" | "idle" | "working" | "attention";
  label: string;
  detail: string;
  progress: number;
}

export function pillStateFor(online: boolean, capsules: Capsule[], pendingApprovals: number): PillState {
  if (!online) {
    return { state: "offline", label: "Jarvis", detail: "daemon offline", progress: 0 };
  }
  const needsYou = capsules.filter((c) => c.needsDecision);
  if (needsYou.length > 0 || pendingApprovals > 0) {
    const count = Math.max(needsYou.length, pendingApprovals);
    return {
      state: "attention",
      label: count === 1 ? "Needs you" : `${count} need you`,
      detail: needsYou[0]?.title ?? "approval waiting",
      progress: 100,
    };
  }
  const running = capsules.filter((c) => c.tone === "running");
  if (running.length > 0) {
    const lead = running[0];
    return {
      state: "working",
      label: lead.stateLabel,
      detail: lead.title,
      progress: lead.progress,
    };
  }
  return { state: "idle", label: "Jarvis", detail: "ready", progress: 0 };
}
