// Reading the local model's second opinion out of a routing decision.
//
// `classification.source` says which classifier produced the answer
// (`heuristic` when the words alone decided it, `local-model` when the local
// classifier changed something), and `classification.signals` carries the
// daemon's own sentence about what it changed. Those sentences are written by
// `Modules/Routing/LocalModelTaskClassifier.Merge`, which ratchets severity up
// and never down:
//
//   local model (qwen2.5-coder:7b) agreed on Standard
//   local model (qwen2.5-coder:7b) raised Standard → Complex
//   local model (qwen2.5-coder:7b) raised risk Medium → High
//   local model (qwen2.5-coder:7b) suggested risk Low; ignored — risk never ratchets down
//   local model (qwen2.5-coder:7b) suggested Trivial; ignored — a second opinion
//     may not downgrade Standard
//
// The fast preview never has any of these — it is the heuristic alone — so this
// is exactly the information the full call adds, and it is worth one line under
// the route sentence.
//
// MIRRORED FILE — the byte-identical twin lives at
// `apps/nexus-desktop/src/bridge/routeSignals.ts`, and
// `apps/forge-ide/test/previewScheduler.test.ts` fails if the two drift.
// Edit one, copy it to the other.

/**
 * The parts of a routing decision this module reads. Deliberately structural
 * and all-optional so both bars' own decision types satisfy it, and so a
 * partial or older wire record degrades to `null` rather than throwing.
 */
export interface RouteFacts {
  classification?: {
    class?: string | null;
    source?: string | null;
    risk?: string | null;
    confidence?: number | null;
    signals?: string[] | null;
    sources?: string[] | null;
  } | null;
  selected?: {
    adapterId?: string | null;
    model?: string | null;
    tier?: string | null;
    estimatedCostUsd?: number | null;
  } | null;
  estimatedCostUsd?: number | null;
  estimateBasis?: string | null;
}

/** `classification.source` when the local classifier moved the answer. */
export const LOCAL_MODEL_SOURCE = "local-model";

export interface LocalModelVerdict {
  /** `raised` is the one that changes what the run will cost and require. */
  kind: "raised" | "agreed" | "deferred";
  /** One short line, already sentence-cased. */
  text: string;
  tone: "ok" | "warn" | "neutral";
  /** The daemon's own wording, verbatim, for the tooltip. */
  detail: string;
}

const RAISED_RISK = /^local model \(([^)]*)\) raised risk (\S+) → (\S+)/i;
const RAISED_CLASS = /^local model \(([^)]*)\) raised (\S+) → (\S+)/i;
const AGREED = /^local model \(([^)]*)\) agreed on (\S+)/i;
const DEFERRED_RISK = /^local model \(([^)]*)\) suggested risk (\S+); ignored/i;
const DEFERRED_CLASS = /^local model \(([^)]*)\) suggested (\S+); ignored/i;

function titleCase(value: string): string {
  return value.length === 0 ? value : value[0].toUpperCase() + value.slice(1);
}

/**
 * The single most consequential thing the local model said, or `null` when it
 * was not consulted. Precedence is raised-risk → raised-class → agreed →
 * deferred: a raise changes the tier floor and the evidence bar, agreement is
 * reassurance, and a deferral is a footnote.
 */
export function localModelVerdict(facts: RouteFacts | null | undefined): LocalModelVerdict | null {
  const classification = facts?.classification;
  if (!classification) return null;
  const signals = classification.signals ?? [];
  const lines = signals.filter((line) => typeof line === "string" && /^local model \(/i.test(line));

  const find = (pattern: RegExp): { line: string; match: RegExpExecArray } | null => {
    for (const line of lines) {
      const match = pattern.exec(line);
      if (match !== null) return { line, match };
    }
    return null;
  };

  const raisedRisk = find(RAISED_RISK);
  if (raisedRisk !== null) {
    return {
      kind: "raised",
      text: `Local model raised the risk to ${titleCase(raisedRisk.match[3])}`,
      tone: "warn",
      detail: raisedRisk.line,
    };
  }

  const raisedClass = find(RAISED_CLASS);
  if (raisedClass !== null) {
    return {
      kind: "raised",
      text: `Local model raised this to ${titleCase(raisedClass.match[3])}`,
      tone: "warn",
      detail: raisedClass.line,
    };
  }

  const agreed = find(AGREED);
  if (agreed !== null) {
    return {
      kind: "agreed",
      text: `Local model agreed on ${titleCase(agreed.match[2])}`,
      tone: "ok",
      detail: agreed.line,
    };
  }

  const deferredRisk = find(DEFERRED_RISK);
  if (deferredRisk !== null) {
    return {
      kind: "deferred",
      text: `Local model read the risk lower (${titleCase(deferredRisk.match[2])}) — risk never ratchets down`,
      tone: "neutral",
      detail: deferredRisk.line,
    };
  }

  const deferredClass = find(DEFERRED_CLASS);
  if (deferredClass !== null) {
    return {
      kind: "deferred",
      text: `Local model read this as ${titleCase(deferredClass.match[2])} — the stronger call stands`,
      tone: "neutral",
      detail: deferredClass.line,
    };
  }

  // Source says it ran, but it phrased itself in a way we do not parse. Say the
  // true, minimal thing rather than inventing a verdict.
  if ((classification.source ?? "").toLowerCase() === LOCAL_MODEL_SOURCE) {
    return {
      kind: "agreed",
      text: "Local model weighed in",
      tone: "neutral",
      detail: `classification.source = ${classification.source}`,
    };
  }
  return null;
}

/**
 * Everything a bar actually renders from one decision, flattened to a string.
 * Two decisions with the same fingerprint look identical on screen, so the
 * full answer replacing a quick estimate only animates when this differs.
 */
export function routeFingerprint(facts: RouteFacts | null | undefined): string {
  if (!facts) return "∅";
  const c = facts.classification ?? {};
  const s = facts.selected ?? {};
  const cost = facts.estimatedCostUsd ?? s.estimatedCostUsd ?? null;
  return [
    c.class ?? "",
    c.risk ?? "",
    s.adapterId ?? "",
    s.model ?? "",
    s.tier ?? "",
    cost === null ? "" : cost.toFixed(4),
    facts.estimateBasis ?? "",
  ].join("|");
}
